	"k8s.io/client-go/tools/clientcmd"
	"k8s.io/client-go/util/retry"
	"sigs.k8s.io/controller-runtime/pkg/client"
	"sigs.k8s.io/controller-runtime/pkg/client/config"
	"sigs.k8s.io/controller-runtime/pkg/controller/controllerutil"
	"sigs.k8s.io/controller-runtime/pkg/handler"
	"sigs.k8s.io/controller-runtime/pkg/manager"
	"sigs.k8s.io/controller-runtime/pkg/reconcile"
	"sigs.k8s.io/controller-runtime/pkg/source"
)

// Constants used in the code.
const (
	stsYaml = `apiVersion: apps/v1
kind: StatefulSet
metadata:
  name: sample
  namespace: default
spec:
  replicas: 3
  serviceName: sample
  selector:
    matchLabels:
      app: sample
  template:
    metadata:
      labels:
        app: sample
    spec:
      containers:
      - name: sample
        image: nginx:1.17-alpine
        ports:
        - containerPort: 80
          name: http
          protocol: TCP
`
)

// statefulSetReconciler is a custom resource reconcile that implements the reconcile.Reconciler interface.
type statefulSetReconciler struct {
	client client.Client
}

// statefulSetWatched returns a handler that adds the reconciler when a StatefulSet is watched.
func statefulSetWatched(r reconcile.Reconciler) handler.EventHandler {
	return handler.EnqueueRequestsFromMapFunc(func(o client.Object) []reconcile.Request {
		requests := []reconcile.Request{}
		if sts, ok := o.(*appsv1.StatefulSet); ok {
			requests = append(requests, reconcile.Request{
				NamespacedName: v1.NamespacedName{
					Name:      sts.Name,
					Namespace: sts.Namespace,
				},
			})
		}
		return requests
	})
}

// Reconcile is the main reconciliation function called by the operator.
func (r *statefulSetReconciler) Reconcile(ctx context.Context, request reconcile.Request) (reconcile.Result, error) {
	sts := &appsv1.StatefulSet{}
	err := r.client.Get(ctx, request.NamespacedName, sts)
	if errors.IsNotFound(err) {
		// Nothing to do, it doesn't exist.
		return reconcile.Result{}, nil
	}
	if err != nil {
		return reconcile.Result{}, err
	}

	// If the StatefulSet isn't stuck, then return.
	if !isStatefulSetStuck(sts) {
		return reconcile.Result{}, nil
	}

	// Otherwise, delete the stuck StatefulSet.
	err = r.client.Delete(ctx, sts, &client.DeleteOptions{})
	if err != nil {
		return reconcile.Result{}, err
	}

	// Wait for the StatefulSet to be deleted before creating it again.
	err = wait.PollImmediate(time.Second, 30*time.Second, func() (bool, error) {
		if err := r.client.Get(ctx, request.NamespacedName, sts); err != nil {
			if errors.IsNotFound(err) {
				return true, nil
			}
			return false, err
		}
		return false, nil
	})
	if err != nil {
		return reconcile.Result{}, err
	}

	// Create the StatefulSet again.
	newSts := &appsv1.StatefulSet{}
	if err := yaml.Unmarshal([]byte(stsYaml), newSts); err != nil {
		return reconcile.Result{}, err
	}

	if err := controllerutil.SetControllerReference(sts, newSts, r.client.Scheme()); err != nil {
		return reconcile.Result{}, err
	}

	err = r.client.Create(ctx, newSts)
	if err != nil {
		return reconcile.Result{}, err
	}

	return reconcile.Result{}, nil
}

// isStatefulSetStuck returns true if the StatefulSet's replica sets are not initializing correctly.
func isStatefulSetStuck(sts *appsv1.StatefulSet) bool {
	if *sts.Spec.Replicas != int32(len(sts.Status.Replicas)) {
		return true
	}

	for i := 0; i < len(sts.Status.Replicas); i++ {
		if sts.Status.Replicas[i].ObservedGeneration != sts.Generation ||
			sts.Status.Replicas[i].ReadyReplicas != 1 ||
			sts.Status.Replicas[i].UpdatedReplicas != 1 ||
			sts.Status.Replicas[i].CurrentReplicas != 1 {
			return true
		}
	}
	return false
}

func main() {
	// Load the Kubernetes configuration.
	cfg, err := config.GetConfig()
	if err != nil {
		panic(fmt.Sprintf("Failed to get Kubernetes config: %v", err))
	}

	// Create a Kubernetes client.
	kubeClient, err := kubernetes.NewForConfig(cfg)
	if err != nil {
		panic(fmt.Sprintf("Failed to create Kubernetes client: %v", err))
	}

	// Create a controller runtime client.
	client, err := client.New(cfg, client.Options{})
	if err != nil {
		panic(fmt.Sprintf("Failed to create controller runtime client: %v", err))
	}

	// Create the StatefulSet.
	sts := &appsv1.StatefulSet{}
	if err := yaml.Unmarshal([]byte(stsYaml), sts); err != nil {
		panic(fmt.Sprintf("Failed to unmarshal StatefulSet YAML: %v", err))
	}

	if err := kubeClient.CoreV1().Services(sts.Namespace).Create(context.Background(), &corev1.Service{
		ObjectMeta: v1.ObjectMeta{
			Name:      sts.Name,
			Namespace: sts.Namespace,
			Labels:    sts.Spec.Selector.MatchLabels,
		},
		Spec: corev1.ServiceSpec{
			Ports: []corev1.ServicePort{{
				Name:     "http",
				Port:     80,
				Protocol: corev1.ProtocolTCP,
			}},
			Selector: sts.Spec.Selector.MatchLabels,
		},
	}, v1.CreateOptions{}); err != nil {
		if errors.IsAlreadyExists(err) {
			fmt.Printf("Service already exists: %s/%s\n", sts.Namespace, sts.Name)
		} else {
			panic(fmt.Sprintf("Failed to create Service: %v", err))
		}
	}

	if err := retry.RetryOnConflict(retry.DefaultBackoff, func() error {
		if err := client.Create(context.Background(), sts); err != nil {
			if errors.IsAlreadyExists(err) {
				fmt.Printf("StatefulSet already exists: %s/%s\n", sts.Namespace, sts.Name)
				return nil
			}
			return err
		}
		return nil
	}); err != nil {
		panic(fmt.Sprintf("Failed to create StatefulSet: %v", err))
	}

	// Set up the reconciler.
	reconciler := &statefulSetReconciler{
		client: client,
	}

	// Set up the manager.
	mgr, err := manager.New(cfg, manager.Options{
		MetricsBindAddress: "0",
		Namespace:          sts.Namespace,
	})
	if err != nil {
		panic(fmt.Sprintf("Failed to create controller runtime manager: %v", err))
	}

	if err := mgr.Add(manager.RunnableFunc(func(stop <-chan struct{}) error {
		return reconciler
	})); err != nil {
		panic(fmt.Sprintf("Failed to add the reconciler to the manager: %v", err))
	}

	// Set up the controller.
	ctrl, err := controller.New("statefulset-controller", mgr, controller.Options{
		Reconciler:              reconciler,
		RateLimiter:             nil,
		MaxConcurrentReconciles: 0,
	})
	if err != nil {
		panic(fmt.Sprintf("Failed to create controller: %v", err))
	}

	// Watch the StatefulSet.
	if err := ctrl.Watch(&source.Kind{Type: &appsv1.StatefulSet{}}, statefulSetWatched(reconciler)); err != nil {
		panic(fmt.Sprintf("Failed to watch StatefulSet: %v", err))
	}

	// Start the manager.
	if err := mgr.Start(stopCh); err != nil {
		panic(fmt.Sprintf("Failed to start the controller runtime manager: %v", err))
	}
}
```

The two code snippets in question refer to the way that ASP.NET Core can create and configure web applications. One of them utilizes the Startup.cs file, while the other uses a WebHostBuilder. Both of these approaches can be used to accomplish the same task, but they differ in their approach, functionality, and reasoning for their usage. 

First, let's take a look at the code snippet that utilizes the Startup.cs file:

```csharp
public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        // Configure Services
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        // Configure the HTTP Request Pipeline
    }
}
```

This approach involves creating a class called Startup that contains two methods: ConfigureServices and Configure. ConfigureServices is used to configure the various services that the application will use, such as database connections, authentication middleware, or anything else required by the application. On the other hand, Configure is used to configure the HTTP Request Pipeline, which is the series of middleware that will handle incoming HTTP requests and send back responses. 

The WebHostBuilder approach, on the other hand, looks something like this:

```csharp
public static void Main(string[] args)
{
    CreateWebHostBuilder(args).Build().Run();
}

public static IWebHostBuilder CreateWebHostBuilder(string[] args) =>
    WebHost.CreateDefaultBuilder(args)
        .ConfigureServices(services =>
        {
            // Configure Services
        })
        .Configure(app =>
        {
            // Configure the HTTP Request Pipeline
        });
```

This approach involves using a WebHostBuilder object to build and configure the web application. The method CreateWebHostBuilder sets up the web host by creating a new instance of the WebHostBuilder class and configuring it with services and middleware. Once the configuration is complete, the Build and Run methods are called to actually start the application.

In terms of functionality, both approaches can be used to achieve the same result. However, there are some differences in the way that they operate. 

The Startup.cs approach is more modular and allows for finer-grained control over the individual components of the application. Because the configuration is separated into distinct methods, it can be easier to manage and maintain over time. Additionally, because the Startup.cs file is part of the project structure, it can be easily located and modified as needed.

On the other hand, the WebHostBuilder approach is more concise and can be easier to use for simple applications that don't require a lot of customization. Because everything is contained within a single method, it can be faster to set up and easier to understand for developers who are unfamiliar with the framework.

The choice between these two approaches ultimately comes down to personal preference and the specific requirements of the application being developed. For more complex applications that require a lot of customization, the Startup.cs approach may be the better option. However, for simple applications that just need to get up and running quickly, the WebHostBuilder approach may be the way to go.

