#include <stddef.h>

static char* mem_start = 0;
static char* mem_end = 0;

void mem_init(void* start, size_t size)
{
    mem_start = (char*)start;
    mem_end = mem_start + size;
    *(size_t*)mem_start = size - sizeof(size_t);
}

void* mem_alloc(size_t size)
{
    // Make sure we have a memory region to work with
    if (mem_start == 0 || mem_end == 0) {
        return 0;
    }

    // Adjust size to ensure alignment
    size_t actual_size = (size + (sizeof(size_t) - 1)) & ~(sizeof(size_t) - 1);

    // Search for a free block of memory
    char* p = mem_start;
    while (p < mem_end) {
        size_t block_size = *(size_t*)p;
        if (block_size >= actual_size) {
            // Found a free block of memory, allocate it
            if (block_size - actual_size > sizeof(size_t)) {
                // Split the block of memory if there's enough space
                *(size_t*)p = actual_size;
                p += actual_size;
                *(size_t*)p = block_size - actual_size;
            } else {
                // Use the whole block of memory
                *(size_t*)p = block_size | 1;
                p += block_size;
            }
            return (void*)(p - block_size + sizeof(size_t));
        }
        p += block_size & ~(size_t)1;
    }

    // No free block of memory found
    return 0;
}

void mem_free(void* ptr)
{
    // Make sure we have a memory region to work with
    if (mem_start == 0 || mem_end == 0) {
        return;
    }

    // Compute the address of the block header
    char* p = (char*)ptr - sizeof(size_t);

    // Mark the block as free
    *(size_t*)p &= ~(size_t)1;

    // Coalesce adjacent free blocks
    char* next_block = p + (*(size_t*)p & ~(size_t)1);
    if (next_block < mem_end && (*(size_t*)next_block & 1) == 0) {
        *(size_t*)p += *(size_t*)next_block;
    }
    char* prev_block = mem_start;
    while (prev_block < p && (*(size_t*)prev_block & 1) == 0) {
        char* prev_block_end = prev_block + (*(size_t*)prev_block & ~(size_t)1);
        if (prev_block_end == p) {
            *(size_t*)prev_block += *(size_t*)p;
            return;
        }
        prev_block = prev_block_end;
    }
}
```

Explanation:

We start by declaring two static variables, `mem_start` and `mem_end`, to keep track of the memory region we're working with. These variables will be initialized to zero, and will be set by the `mem_init` function.

The `mem_init` function takes a pointer to the start of the memory region and its size, and initializes `mem_start` and `mem_end` accordingly. It also writes the size of the memory region in the first 8 bytes, so that we can keep track of how much memory is left.

The `mem_alloc` function takes a size parameter and returns a pointer to a block of memory of that size, or zero if no block of sufficient size can be found. We adjust the size to ensure alignment to the word size, so that we can store the size of the block in the first 8 bytes. We then search the memory region for a free block of sufficient size. We use a while loop to iterate over the memory region, and use a pointer to track our progress. We read the size of the block from the first 8 bytes, and check if it's free and large enough to hold the requested size. If it is, we allocate the block and return a pointer to the user. If the block is larger than the requested size, we split it into two blocks, and update their sizes accordingly. We then return a pointer to the user. If no free block of sufficient size can be found, we return zero.

The `mem_free` function takes a pointer to a block of memory that was previously allocated, and frees it. We start by computing the address of the block header, which contains the size of the block and a flag indicating whether it's free or not. We then clear the flag, marking the block as free. We then check if the next block of memory is free, and if so, we coalesce the two blocks into one. We also check if the previous block of memory is free, and if so, we coalesce the two blocks into one.

