var itemFeatures = map[string][]float64{
    "Item1": {0.2, 0.4, 0.1},
    "Item2": {0.4, 0.1, 0.5},
    "Item3": {0.1, 0.3, 0.4},
    "Item4": {0.6, 0.2, 0.3},
}
// Define a function to calculate the cosine similarity between two vectors
func cosineSimilarity(a, b []float64) float64 {
    dotProduct := 0.0
    normA := 0.0
    normB := 0.0
    for i := 0; i < len(a); i++ {
        dotProduct += a[i] * b[i]
        normA += math.Pow(a[i], 2)
        normB += math.Pow(b[i], 2)
    }
    return dotProduct / (math.Sqrt(normA) * math.Sqrt(normB))
}
// Define a function to get the top-N most similar items to a given item
func getTopNSimilarItems(item string, n int) []string {
    similarities := make(map[string]float64)
    for i, features := range itemFeatures {
        if i != item {
            similarities[i] = cosineSimilarity(itemFeatures[item], features)
        }
    }
    sortedItems := make([]string, 0, len(similarities))
    for i := 0; i < n; i++ {
        maxSimilarity := 0.0
        maxItem := ""
        for i, similarity := range similarities {
            if similarity > maxSimilarity {
                maxSimilarity = similarity
                maxItem = i
            }
        }
        if maxItem != "" {
            sortedItems = append(sortedItems, maxItem)
            delete(similarities, maxItem)
        } else {
            break
        }
    }
    return sortedItems
}
// Define a function to get the top-N recommended items for a given user
func getTopNRecommendations(user string, n int) []string {
    preferences := userPreferences[user]
    recommendations := make(map[string]float64)
    for item, rating := range preferences {
        similarItems := getTopNSimilarItems(item, 3)
        for _, similarItem := range similarItems {
            if _, ok := preferences[similarItem]; !ok {
                recommendations[similarItem] += rating * cosineSimilarity(itemFeatures[item], itemFeatures[similarItem])
            }
        }
    }
    sortedItems := make([]string, 0, len(recommendations))
    for i := 0; i < n; i++ {
        maxScore := 0.0
        maxItem := ""
        for item, score := range recommendations {
            if score > maxScore {
                maxScore = score
                maxItem = item
            }
        }
        if maxItem != "" {
            sortedItems = append(sortedItems, maxItem)
            delete(recommendations, maxItem)
        } else {
            break
        }
    }
    return sortedItems
}
func main() {
