using System;
using System.IO;
using System.Text;
namespace ReportGenerator
{
    class Program
    {
        static void Main(string[] args)
        {
            // Family member data
            string[] familyMembers = { "John", "Jane", "David", "Sara" };
            int[] ages = { 35, 32, 6, 4 };
            // Beach data
            string location = "Myrtle Beach";
            string[] activities = { "swimming", "building sandcastles", "playing volleyball" };
