import org.apache.spark.sql.functions._
import org.apache.spark.sql.types._

def cleanData(data: DataFrame, criteria: Map[String, String]): DataFrame = {
  var cleanedData = data

  // Apply cleaning tasks based on criteria
  if (criteria.getOrElse("remove_duplicates", "false") == "true") {
    cleanedData = cleanedData.dropDuplicates()
  }

  if (criteria.getOrElse("remove_empty_rows", "false") == "true") {
