def binary_search_word(file_name, word, max_lines):
    try:
        with open(file_name, 'r') as file:
            lines = file.readlines()[:max_lines] # read up to max_lines
    except FileNotFoundError:
        return "Error: file not found."

    left, right = 0, len(lines) - 1

    while left <= right:
        mid = (left + right) // 2
        line = lines[mid].strip()

        if line == word:
            return mid + 1 # return line number, not index
        elif line < word:
            left = mid + 1
        else:
            right = mid - 1

    return -1 # word not found

