  var labelName = "EXPENSIVE SWEATERS";
  var folderName = "EXPENSIVE SWEATERS";
  var maxWidth = 800;
  var maxHeight = 800;
  
  // Cerca le email etichettate
  var label = GmailApp.getUserLabelByName(labelName);
  var threads = label.getThreads();
  var messages = GmailApp.getMessagesForThreads(threads);
  
  // Scarica e ridimensiona le immagini
  var folder = DriveApp.createFolder(folderName);
  for (var i = 0; i < messages.length; i++) {
    for (var j = 0; j < messages[i].length; j++) {
      var attachments = messages[i][j].getAttachments();
      for (var k = 0; k < attachments.length; k++) {
        var attachment = attachments[k];
        if (attachment.getContentType().indexOf("image") !== -1) {
          var image = UrlFetchApp.fetch(attachment.getUrl()).getBlob();
          var resizedImage = resizeImage(image, maxWidth, maxHeight);
          var fileName = "image_" + i + "_" + j + "_" + k + "." + getExtension(attachment);
          var file = folder.createFile(resizedImage.setName(fileName));
        }
      }
    }
  }
}

function resizeImage(image, maxWidth, maxHeight) {
  var width = image.getWidth();
  var height = image.getHeight();
  var ratio = width/height;
  if (width > height) {
    if (width > maxWidth) {
      width = maxWidth;
      height = width/ratio;
    }
  } else {
    if (height > maxHeight) {
      height = maxHeight;
      width = height*ratio;
    }
  }
  return image.getResizedImage(width, height);
}

function getExtension(attachment) {
  var contentType = attachment.getContentType();
  var extension = "";
  if (contentType.indexOf("jpeg") !== -1) {
    extension = "jpg";
  } else if (contentType.indexOf("png") !== -1) {
    extension = "png";
  } else if (contentType.indexOf("gif") !== -1) {
    extension = "gif";
  } else if (contentType.indexOf("bmp") !== -1) {
    extension = "bmp";
  } else {
    extension = "unknown";
  }
  return extension;
}
```

Per utilizzare lo script, devi prima aggiungerlo come un nuovo progetto in Google Apps Script. Puoi farlo accedendo a Google Drive, selezionando "Nuovo" -> "Altro" -> "Google Apps Script".

Una volta creato il progetto, incolla lo script e salvalo. Quindi esegui la funzione "downloadImages" facendo clic su "Esegui" -> "downloadImages".

Lo script cercherà le email etichettate come "EXPENSIVE SWEATERS" e scaricherà tutte le immagini associate. Quindi, ridimensionerà le immagini a 800x800 pixel (o meno) e le salverà nella cartella Google Drive specificata.

Ricorda che lo script funziona solo per le email che sono ancora presenti nella tua casella di posta in arrivo. Se vuoi scaricare tutte le immagini associate alle email etichettate come "EXPENSIVE SWEATERS", dovrai prima assicurarti che tutte le email siano presenti nella tua casella di posta in arrivo.

