```javascript
const fs = require('fs');
const path = require('path');

function readFiles(dirPath) {
	let files = fs.readdirSync(dirPath);
	let fileDetails = [];

	files.forEach((file) => {
		let filePath = path.join(dirPath, file);
		let stats = fs.statSync(filePath);

		if(stats.isFile()) {
			let extName = path.extname(filePath).toLowerCase();
			let fileSize = stats.size;
			let createdDate = stats.birthtime.toLocaleDateString();
			let modifiedDate = stats.mtime.toLocaleDateString();

			let fileObj = {
				name: file,
				extension: extName,
				size: fileSize,
				created: createdDate,
				modified: modifiedDate
			}

			fileDetails.push(fileObj);
		}
	});

	return fileDetails;
}
```

We have used the fs.readdirSync() method to read the files in the specified directory synchronously. We have then iterated over each file using forEach() method and created an object with the required file details. We have used the path.extname() method to get the file extension, fs.statSync() method to get the file size, and stats.birthtime and stats.mtime properties to get the creation and modified dates respectively. We have pushed each file object into an array called 'fileDetails' and returned it.

