	let filteredFiles = files.filter((file) => {
		if(fileTypeFilter && !file.extension.includes(fileTypeFilter)) {
			return false;
		}

		if(fileSizeFilter && file.size < fileSizeFilter) {
			return false;
		}

		return true;
	});

	return filteredFiles;
}
```

