```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <stdexcept>
#include <cstring>
#include <cstdlib>
#include <unistd.h>
#include <sqlite3.h>
#include <mqtt/async_client.h>
#include <nlohmann/json.hpp>
#include <inotify-cpp/Inotify.h>

using json = nlohmann::json;
using namespace std::chrono_literals;

// MQTT client configuration
struct mqtt_config {
    std::string broker_address;
    std::string client_id;
    std::string username;
    std::string password;
    std::vector<std::string> topics;
};

// SQLite database configuration
struct sqlite_config {
    std::string db_file;
    std::string table_name;
};

// Worker thread that inserts MQTT messages into SQLite databases
void worker_thread(const mqtt_config& mqtt_cfg, const sqlite_config& sqlite_cfg, std::condition_variable& cv, std::mutex& mtx) {
    try {
        std::cout << "Worker thread started for " << mqtt_cfg.broker_address << " / " << sqlite_cfg.db_file << std::endl;

        // Connect to the SQLite database
        sqlite3* db = nullptr;
        if (sqlite3_open(sqlite_cfg.db_file.c_str(), &db) != SQLITE_OK) {
            throw std::runtime_error("Failed to open SQLite database " + sqlite_cfg.db_file + ": " + sqlite3_errmsg(db));
        }

        // Create the table if it does not exist
        std::string create_table_sql = "CREATE TABLE IF NOT EXISTS " + sqlite_cfg.table_name + " (topic TEXT, message TEXT, timestamp INTEGER)";
        if (sqlite3_exec(db, create_table_sql.c_str(), nullptr, nullptr, nullptr) != SQLITE_OK) {
            throw std::runtime_error("Failed to create table " + sqlite_cfg.table_name + ": " + sqlite3_errmsg(db));
        }

        // Connect to the MQTT broker
        mqtt::async_client client(mqtt_cfg.broker_address, mqtt_cfg.client_id);
        mqtt::connect_options connOpts;
        connOpts.set_keep_alive_interval(60);
        connOpts.set_clean_session(true);
        if (!mqtt_cfg.username.empty()) {
            connOpts.set_user_name(mqtt_cfg.username);
            connOpts.set_password(mqtt_cfg.password);
        }

        // Subscribe to the MQTT topics
        std::vector<mqtt::topic> topics;
        for (const auto& topic : mqtt_cfg.topics) {
            topics.emplace_back(client, topic, 0);
        }
        client.start_consuming();

        // Callback for handling MQTT messages
        auto on_message = [&](const mqtt::const_message_ptr& msg) {
            std::lock_guard<std::mutex> lock(mtx);

            // Insert the message into the SQLite database
            std::string insert_sql = "INSERT INTO " + sqlite_cfg.table_name + " (topic, message, timestamp) VALUES (?, ?, ?)";
            sqlite3_stmt* stmt = nullptr;
            if (sqlite3_prepare_v2(db, insert_sql.c_str(), -1, &stmt, nullptr) != SQLITE_OK) {
                std::cerr << "Failed to prepare insert statement for " << mqtt_cfg.broker_address << ": " << sqlite3_errmsg(db) << std::endl;
                return;
            }
            sqlite3_bind_text(stmt, 1, msg->get_topic().c_str(), -1, SQLITE_TRANSIENT);
            sqlite3_bind_text(stmt, 2, reinterpret_cast<const char*>(msg->get_payload().data()), msg->get_payload().size(), SQLITE_TRANSIENT);
            sqlite3_bind_int64(stmt, 3, std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch()).count());
            if (sqlite3_step(stmt) != SQLITE_DONE) {
                std::cerr << "Failed to insert message into " << sqlite_cfg.db_file << ": " << sqlite3_errmsg(db) << std::endl;
            }
            sqlite3_finalize(stmt);
        };

        // Subscribe to the MQTT topics and start consuming messages
        for (auto& topic : topics) {
            topic.set_callback(on_message);
            client.subscribe(topic);
        }

        // Wait for MQTT messages or a stop signal from the main thread
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock);
        client.unsubscribe(topics);
        client.stop_consuming();
    } catch (const std::exception& ex) {
        std::cerr << "Worker thread exception: " << ex.what() << std::endl;
    }
}

// Main function that reads the configuration file and starts the worker threads
int main(int argc, char* argv[]) {
    try {
        // Parse the command line arguments
        if (argc != 2) {
            std::cerr << "Usage: " << argv[0] << " <config_file>" << std::endl;
            return 1;
        }
        std::string config_file = argv[1];

        // Watch the configuration file for changes and reload the configuration
        inotify::Inotify notifier;
        notifier.addWatch(config_file, IN_MODIFY);
        std::condition_variable cv;
        std::mutex mtx;
        std::thread watcher_thread([&]() {
            while (true) {
                inotify::Event event;
                if (notifier.getNextEvent(event)) {
                    std::unique_lock<std::mutex> lock(mtx);
                    std::cout << "Configuration file modified, reloading..." << std::endl;
                    cv.notify_all();
                }
                std::this_thread::sleep_for(100ms);
            }
        });

        // Load the configuration from the file
        json config;
        std::ifstream file(config_file);
        if (!file) {
            throw std::runtime_error("Failed to open configuration file " + config_file);
        }
        file >> config;

        // Start the worker threads for each MQTT broker / SQLite database combination
        std::vector<std::thread> threads;
        for (const auto& mqtt_cfg : config["mqtt"]) {
            for (const auto& sqlite_cfg : config["sqlite"]) {
                threads.emplace_back(worker_thread, mqtt_cfg, sqlite_cfg, std::ref(cv), std::ref(mtx));
            }
        }

        // Wait for the stop signal from the user
        std::cout << "Press Ctrl+C to stop." << std::endl;
        while (true) {
            std::this_thread::sleep_for(1s);
        }

        // Stop the worker threads
        cv.notify_all();
        for (auto& t : threads) {
            t.join();
        }

        return 0;
    } catch (const std::exception& ex) {
        std::cerr << "Exception: " << ex.what() << std::endl;
        return 1;
    }
}
```

This code uses the Eclipse Paho MQTT C++ library for MQTT communication and the nlohmann/json library for JSON parsing. The SQLite database connection and manipulation is done using the standard SQLite C API. The Inotify library is used for monitoring changes to the configuration file.

