function findCommonSubsequences($string1, $string2) {
    $length1 = strlen($string1);
    $length2 = strlen($string2);
    $lcs = array();
    for ($i = 0; $i < $length1; $i++) {
        for ($j = 0; $j < $length2; $j++) {
            if ($string1[$i] == $string2[$j]) {
                if (!isset($lcs[$i - 1][$j - 1])) {
                    $lcs[$i - 1][$j - 1] = 0;
                }
                $lcs[$i][$j] = $lcs[$i - 1][$j - 1] + 1;
            } else {
                $lcs[$i][$j] = 0;
            }
        }
    }
    $max = 0;
    $result = array();
    for ($i = 0; $i < $length1; $i++) {
        for ($j = 0; $j < $length2; $j++) {
            if ($lcs[$i][$j] > $max) {
                $max = $lcs[$i][$j];
                $result = array();
                $result[] = substr($string1, $i - $max + 1, $max);
            } else if ($lcs[$i][$j] == $max) {
                $result[] = substr($string1, $i - $max + 1, $max);
            }
        }
    }
    $result = array_unique($result);
    $result = array_values($result);
    usort($result, function($a, $b) {
        return strlen($b) - strlen($a);
    });
    return array_slice($result, 0, 3);
}
