Implementing a comprehensive security system for APIs requires a combination of different technologies and best practices. Here's an example of how to implement such a system using the following libraries:

- Express.js: A web framework for Node.js that simplifies the creation of RESTful APIs.
- Helmet: A set of middleware functions to help secure Express.js applications by setting various HTTP headers.
- Passport: A popular authentication middleware for Node.js that supports a variety of authentication strategies.
- express-rate-limit: A middleware for Express.js that limits the number of requests from the same IP address.
- jsonwebtoken: A library for generating and verifying JSON Web Tokens (JWTs) for user authentication and authorization.
- Morgan: A middleware for logging HTTP requests.

```javascript
const express = require('express');
const helmet = require('helmet');
const passport = require('passport');
const { Strategy: JwtStrategy, ExtractJwt } = require('passport-jwt');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');

const app = express();

// Set security-related HTTP headers with helmet
app.use(helmet());

// Log HTTP requests with Morgan
app.use(morgan('combined'));

// Set up rate limiter middleware to prevent excessive requests
const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 10, // limit each IP to 10 requests per windowMs
  message: 'Too many requests from this IP, please try again in a minute',
});
app.use(limiter);

// Set up authentication middleware with Passport and JWT
const jwtOptions = {
  jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
  secretOrKey: 'my-secret-key', // replace with your own secret key
};

passport.use(new JwtStrategy(jwtOptions, (jwtPayload, done) => {
  // Here you would typically check if the user specified in jwtPayload
  // exists in your database and return the user object if found,
  // or null if not found.
  if (jwtPayload.sub === 'john.doe@example.com') {
    done(null, { email: 'john.doe@example.com' });
  } else {
    done(null, false);
  }
}));

app.use(passport.initialize());

// Set up authorization middleware with Passport
const requireJwtAuth = passport.authenticate('jwt', { session: false });

// Example API endpoint that requires authentication and authorization
app.get('/api/data', requireJwtAuth, (req, res) => {
  // Here you would typically fetch the data from your database based
  // on the user object available in req.user, and send it back as a JSON response.
  res.json({ data: 'secret data' });
});

// Example login endpoint that generates a JWT
app.post('/login', (req, res) => {
  // Here you would typically check if the user credentials provided in
  // req.body are valid and return the user object if valid,
  // or null if invalid.
  if (req.body.email === 'john.doe@example.com' && req.body.password === 'secret') {
    const token = jwt.sign({ sub: 'john.doe@example.com' }, jwtOptions.secretOrKey);
    res.json({ token });
  } else {
    res.sendStatus(401);
  }
});

// Start the server
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

The code sets up the following security measures:

1. Set security-related HTTP headers with `helmet` to prevent common web vulnerabilities.
2. Log HTTP requests with `morgan` to keep track of all incoming requests and responses.
3. Limit the number of requests from the same IP address using `express-rate-limit` to prevent brute-force and denial-of-service attacks.
4. Authenticate and authorize API requests using `Passport` and `jsonwebtoken` to ensure that only authenticated and authorized users can access sensitive data.
5. Provide a login endpoint that generates a JWT for authenticated users.

