        self.__hint_text = "Hint: "

    def test(self):
        while self.__attempts > 0:
            answer = input("What melts faster, ice or snow? ").lower()
            if answer == "ice":
                print("Correct!")
                self.__attempts -= 1
            else:
                self.__attempts -= 1
                if self.__attempts == 0:
                    print("Incorrect. You have no more attempts.")
                    return False
                else:
