2. Modify the `App.vue` component to display the `FeedTable` component:

```
<template>
  <div class="container mt-3">
    <ul class="nav nav-tabs mb-3">
      <li class="nav-item">
        <a class="nav-link" :class="{ active: activeTab === 'parsed' }" href="#" @click.prevent="activeTab = 'parsed'">Parsed Feed</a>
      </li>
      <li class="nav-item">
        <a class="nav-link" :class="{ active: activeTab === 'generated' }" href="#" @click.prevent="activeTab = 'generated'">Generated Feed</a>
      </li>
    </ul>
