      <h2>Parsed RSS Feed</h2>
      <feed-table :items="parsedFeedItems" />
    </div>
    <div v-show="activeTab === 'generated'">
      <h2>Generated RSS Feed</h2>
      <feed-table :items="generatedFeedItems" />
    </div>
  </div>
</template>

<script>
import FeedTable from './components/FeedTable.vue'
import parser from 'rss-parser'

export default {
  name: 'App',
  components: {
    FeedTable,
  },
  data() {
    return {
      activeTab: 'parsed',
      parsedFeedItems: [],
      generatedFeedItems: [],
    }
  },
  mounted() {
    this.fetchParsedFeed()
    this.fetchGeneratedFeed()
    setInterval(() => {
      this.fetchParsedFeed()
      this.fetchGeneratedFeed()
    }, 5 * 60 * 1000)
  },
  methods: {
    async fetchParsedFeed() {
      const feed = await parser.parseURL('https://www.reddit.com/.rss')
      this.parsedFeedItems = feed.items
    },
    async fetchGeneratedFeed() {
      const feed = await parser.parseURL('https://www.reddit.com/.rss')
      this.generatedFeedItems = feed.items.filter(item => item.categories.includes('News'))
    },
  },
}
</script>

<style>
