Here is a code snippet for a FreeRTOS project on STM32F4 microcontroller that implements three tasks, handles interrupts and communicates between tasks using a message queue. The tasks include an LED toggle task, a UART task that sends and receives messages, and a button interrupt task that toggles the LED on button press. 

```c
// Include necessary headers
#include "stm32f4xx.h"
#include "FreeRTOS.h"
#include "task.h"
#include "queue.h"

// Define the LED toggle task
void vLEDTask(void *pvParameters)
{
  for(;;)
  {
    GPIO_ToggleBits(GPIOD, GPIO_Pin_12); // Toggle LED on PD12
    vTaskDelay(pdMS_TO_TICKS(500)); // Delay for 500ms
  }
}

// Define the UART task
void vUARTTask(void *pvParameters)
{
  char tx_message[20] = "Hello from UART\n";
  char rx_message[20];

  for(;;)
  {
    // Send message on UART
    for(int i = 0; i < strlen(tx_message); i++)
    {
      USART_SendData(USART2, tx_message[i]);
      while(USART_GetFlagStatus(USART2, USART_FLAG_TXE) == RESET);
    }
    vTaskDelay(pdMS_TO_TICKS(1000)); // Delay for 1s

    // Receive message on UART
    int idx = 0;
    while(USART_GetFlagStatus(USART2, USART_FLAG_RXNE) == RESET);
    rx_message[idx] = USART_ReceiveData(USART2);
    while(rx_message[idx] != '\n')
    {
      idx++;
      while(USART_GetFlagStatus(USART2, USART_FLAG_RXNE) == RESET);
      rx_message[idx] = USART_ReceiveData(USART2);
    }
    rx_message[idx] = '\0';
    printf("Received: %s\n", rx_message);
  }
}

// Define the button interrupt task
void EXTI0_IRQHandler(void)
{
  if(EXTI_GetITStatus(EXTI_Line0) != RESET)
  {
    GPIO_ToggleBits(GPIOD, GPIO_Pin_12); // Toggle LED on PD12
    EXTI_ClearITPendingBit(EXTI_Line0); // Clear the interrupt flag
  }
}

// Define the main function
int main(void)
{
  // Initialize GPIO and USART
  GPIO_InitTypeDef GPIO_InitStructure;
  USART_InitTypeDef USART_InitStructure;

  // Enable clocks
  RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOD, ENABLE);
  RCC_APB1PeriphClockCmd(RCC_APB1Periph_USART2, ENABLE);
  RCC_APB2PeriphClockCmd(RCC_APB2Periph_SYSCFG, ENABLE);

  // Configure GPIO for LED
  GPIO_InitStructure.GPIO_Pin = GPIO_Pin_12;
  GPIO_InitStructure.GPIO_Mode = GPIO_Mode_OUT;
  GPIO_InitStructure.GPIO_OType = GPIO_OType_PP;
  GPIO_InitStructure.GPIO_Speed = GPIO_Speed_100MHz;
  GPIO_InitStructure.GPIO_PuPd = GPIO_PuPd_NOPULL;
  GPIO_Init(GPIOD, &GPIO_InitStructure);

  // Configure GPIO for button
  GPIO_InitStructure.GPIO_Pin = GPIO_Pin_0;
  GPIO_InitStructure.GPIO_Mode = GPIO_Mode_IN;
  GPIO_InitStructure.GPIO_OType = GPIO_OType_PP;
  GPIO_InitStructure.GPIO_Speed = GPIO_Speed_100MHz;
  GPIO_InitStructure.GPIO_PuPd = GPIO_PuPd_DOWN;
  GPIO_Init(GPIOA, &GPIO_InitStructure);

  // Configure USART
  USART_InitStructure.USART_BaudRate = 115200;
  USART_InitStructure.USART_WordLength = USART_WordLength_8b;
  USART_InitStructure.USART_StopBits = USART_StopBits_1;
  USART_InitStructure.USART_Parity = USART_Parity_No;
  USART_InitStructure.USART_HardwareFlowControl = USART_HardwareFlowControl_None;
  USART_InitStructure.USART_Mode = USART_Mode_Tx | USART_Mode_Rx;
  USART_Init(USART2, &USART_InitStructure);

  // Enable USART and interrupts
  USART_Cmd(USART2, ENABLE);
  NVIC_EnableIRQ(USART2_IRQn);
  NVIC_EnableIRQ(EXTI0_IRQn);
  USART_ITConfig(USART2, USART_IT_RXNE, ENABLE);

  // Create LED toggle task
  xTaskCreate(vLEDTask, "LED Task", configMINIMAL_STACK_SIZE, NULL, tskIDLE_PRIORITY + 1, NULL);

  // Create UART task
  xTaskCreate(vUARTTask, "UART Task", configMINIMAL_STACK_SIZE, NULL, tskIDLE_PRIORITY + 2, NULL);

  // Create a message queue
  xQueueHandle xQueue = xQueueCreate(10, sizeof(char[20]));

  // Start the scheduler
  vTaskStartScheduler();

  for(;;);
}
```

This code snippet defines three tasks, an LED toggle task, a UART task, and a button interrupt task. The LED and button are connected to pins PD12 and PA0 respectively. The UART is configured to use USART2 and communicates at a baud rate of 115200. The UART task sends a message "Hello from UART" every second and receives messages from the console via interrupt. The button interrupt task toggles the LED when the button is pressed.

The code also creates a message queue that can hold up to 10 messages of size 20 bytes. This is used to communicate between the LED and UART tasks. When the LED task toggles the LED, it sends a message "LED toggled" to the queue. The UART task waits for messages on the queue and prints them to the console when it receives them.

Overall, this code demonstrates the use of FreeRTOS to implement concurrent tasks, interrupt handling, and communication between tasks using a message queue.

