type UserValidationBolt struct {
  collector bolt.Collector
  db        *sql.DB
}

func (b *UserValidationBolt) Prepare(conf map[string]interface{}, context bolt.TopologyContext, collector bolt.Collector) {
  b.collector = collector

  db, err := sql.Open("mysql", "user:password@/db_name")
  if err != nil {
    panic(err.Error())
  }
  b.db = db
}

func (b *UserValidationBolt) Execute(tuple *bolt.Tuple) {
  username := tuple.GetStringByField("username")
  password := tuple.GetStringByField("password")

  // Check if user exists in the database
  stmt, err := b.db.Prepare("SELECT * FROM users WHERE username = ?")
  if err != nil {
    panic(err.Error())
  }
  defer stmt.Close()
  rows, err := stmt.Query(username)
  if err != nil {
    panic(err.Error())
  }

  if rows.Next() {
    // User exists, validate password
    var id int
    var hashedPassword string
    err = rows.Scan(&id, &hashedPassword)
    if err != nil {
      panic(err.Error())
    }

    match := CheckPasswordHash(password, hashedPassword)
    if !match {
      b.collector.Emit(tuple, []string{"invalid-password"})
    } else {
      b.collector.Emit(tuple, []string{"valid-credentials"})
    }
  } else {
    // User does not exist
    b.collector.Emit(tuple, []string{"invalid-username"})
  }
}

func CheckPasswordHash(password, hash string) bool {
  err := bcrypt.CompareHashAndPassword([]byte(hash), []byte(password))
  return err == nil
}

func main() {
  conf := storm.NewTopologyConfig()
  conf.Name = "user-validation-topology"

  spoutConf := storm.NewSpoutConfig(new(UserValidationSpout))
  spoutConf.Name = "user-validation-spout"

  boltConf := storm.NewBoltConfig(new(UserValidationBolt))
  boltConf.Name = "user-validation-bolt"
  boltConf.ParallelismHint = 2
  boltConf.OutputFields = []string{"valid-credentials", "invalid-username", "invalid-password"}

  conf.SetSpout("user-validation-spout", spoutConf, 1)
  conf.SetBolt("user-validation-bolt", boltConf, 1).ShuffleGrouping("user-validation-spout")

  client, err := storm.Connect()
  if err != nil {
    panic(err)
  }
  defer client.Close()

  client.SubmitTopology(conf)
}
```

