Sure, here's a Swift function that conducts subject-verb agreement verification, resolves any errors found, and identifies the type of the sentence:
```swift
func verifySubjectVerbAgreement(sentence: String) -> (Bool, String, String) {
    let sentenceType = getSentenceType(sentence: sentence)
    var correctedSentence = ""
    var hasError = false

    // Check subject-verb agreement based on sentence type
    switch sentenceType {
    case "declarative":
        correctedSentence = checkDeclarativeSentence(sentence: sentence, hasError: &hasError)
    case "interrogative":
        correctedSentence = checkInterrogativeSentence(sentence: sentence, hasError: &hasError)
    case "imperative":
        correctedSentence = checkImperativeSentence(sentence: sentence, hasError: &hasError)
    case "exclamatory":
        correctedSentence = checkExclamatorySentence(sentence: sentence, hasError: &hasError)
    default:
        // Invalid sentence type
        return (false, "", "")
    }

    return (hasError ? false : true, correctedSentence, sentenceType)
}
// Helper function to identify the sentence type
func getSentenceType(sentence: String) -> String {
    let lastChar = sentence.last
    switch lastChar {
    case "?":
        return "interrogative"
    case "!":
        return "exclamatory"
    default:
        if sentence.hasSuffix(".") {
            return "declarative"
        } else {
            return "imperative"
        }
    }
}
// Helper function to check subject-verb agreement in a declarative sentence
func checkDeclarativeSentence(sentence: String, hasError: inout Bool) -> String {
    var words = sentence.components(separatedBy: " ")
    let verbIndex = findVerbIndex(words: words)

    // Check subject-verb agreement
    if verbIndex > 0 && verbIndex < words.count {
        let subject = words[verbIndex - 1]
        let verb = words[verbIndex]
        if !isSingular(subject: subject) && isSingular(verb: verb) {
            words[verbIndex] = makePlural(word: verb)
            hasError = true
        } else if isSingular(subject: subject) && !isSingular(verb: verb) {
            words[verbIndex] = makeSingular(word: verb)
            hasError = true
        }
    }

    return words.joined(separator: " ")
}
// Helper function to check subject-verb agreement in an interrogative sentence
func checkInterrogativeSentence(sentence: String, hasError: inout Bool) -> String {
    var words = sentence.components(separatedBy: " ")
    let verbIndex = findVerbIndex(words: words)

    // Check subject-verb agreement
    if verbIndex > 0 && verbIndex < words.count {
        let subject = words[verbIndex - 1]
        let verb = words[verbIndex]
        if !isSingular(subject: subject) && isSingular(verb: verb) {
            words[verbIndex] = makePlural(word: verb)
            hasError = true
        } else if isSingular(subject: subject) && !isSingular(verb: verb) {
            words[verbIndex] = makeSingular(word: verb)
            hasError = true
        }
    }

    return words.joined(separator: " ")
}
// Helper function to check subject-verb agreement in an imperative sentence
func checkImperativeSentence(sentence: String, hasError: inout Bool) -> String {
    // Imperative sentences do not have a subject, so no need to check subject-verb agreement
    return sentence
}
// Helper function to check subject-verb agreement in an exclamatory sentence
func checkExclamatorySentence(sentence: String, hasError: inout Bool) -> String {
    var words = sentence.components(separatedBy: " ")
    let verbIndex = findVerbIndex(words: words)

    // Check subject-verb agreement
    if verbIndex > 0 && verbIndex < words.count {
        let subject = words[verbIndex - 1]
        let verb = words[verbIndex]
        if !isSingular(subject: subject) && isSingular(verb: verb) {
            words[verbIndex] = makePlural(word: verb)
            hasError = true
        } else if isSingular(subject: subject) && !isSingular(verb: verb) {
            words[verbIndex] = makeSingular(word: verb)
            hasError = true
        }
    }

    return words.joined(separator: " ")
}
// Helper function to find the index of the verb in a sentence
func findVerbIndex(words: [String]) -> Int {
    for (index, word) in words.enumerated() {
        if isVerb(word: word) {
            return index
        }
    }
    return -1
}
// Helper function to check if a word is a verb
func isVerb(word: String) -> Bool {
    let verbRegex = try! NSRegularExpression(pattern: "(\\w+ed$|\\w+ing$|\\w+s$|\\b(be|am|is|are|was|were|been|being)\\b)", options: .caseInsensitive)
    let range = NSRange(location: 0, length: word.utf16.count)
    let match = verbRegex.firstMatch(in: word, options: [], range: range)
    return match != nil
}
// Helper function to check if a word is singular
func isSingular(word: String) -> Bool {
    let singularRegex = try! NSRegularExpression(pattern: "\\b(it|he|she|this|that|each|either|neither|one)\\b", options: .caseInsensitive)
    let range = NSRange(location: 0, length: word.utf16.count)
    let match = singularRegex.firstMatch(in: word, options: [], range: range)
    return match != nil
}
// Helper function to make a word plural
func makePlural(word: String) -> String {
    if word.hasSuffix("y") {
        return String(word.dropLast()) + "ies"
    } else if word.hasSuffix("s") {
        return word + "es"
    } else {
        return word + "s"
    }
}
// Helper function to make a word singular
func makeSingular(word: String) -> String {
    if word.hasSuffix("ies") {
        return String(word.dropLast(3)) + "y"
    } else if word.hasSuffix("es") {
        return String(word.dropLast(2))
    } else if word.hasSuffix("s") {
        return String(word.dropLast())
    } else {
        return word
    }
}
```
This function takes a sentence as a string parameter and returns a tuple containing a Boolean value indicating whether the sentence has the right subject-verb agreement, a string representing the corrected sentence if an error was found, and a string representing the sentence type. 
The `getSentenceType` function identifies the type of the sentence based on the last character of the sentence. The `checkDeclarativeSentence`, `checkInterrogativeSentence`, `checkImperativeSentence`, and `checkExclamatorySentence` functions check subject-verb agreement based on the sentence type. The `findVerbIndex`, `isVerb`, `isSingular`, `makePlural`, and `makeSingular` functions are helper functions used to check subject-verb agreement and modify the sentence if necessary. 
Note that this function uses regular expressions to identify verbs and singular words. This approach may not be perfect, but it should work for most cases.

