Here is a TypeScript function that takes an array of color scheme objects, calculates the contrast ratio for each pair of colors, rounds the result to two decimal places, and adds the result as an extra property to each object. The function also provides a warning message if the contrast ratio is lower than the recommended WCAG value:

```typescript
interface ColorScheme {
  color1: string;
  color2: string;
  contrastRatio?: number;
}

function assessAccessibility(colorSchemes: ColorScheme[]): void {
  const wcagContrastRatio = 4.5;

  for (let i = 0; i < colorSchemes.length; i++) {
    const color1 = colorSchemes[i].color1;
    const color2 = colorSchemes[i].color2;

    // Convert colors to RGB
    const color1Rgb = hexToRgb(color1);
    const color2Rgb = hexToRgb(color2);

    // Calculate relative luminance for each color
    const l1 = calculateRelativeLuminance(color1Rgb);
    const l2 = calculateRelativeLuminance(color2Rgb);

    // Calculate contrast ratio using WCAG formula
    const contrastRatio = calculateContrastRatio(l1, l2);

    // Round the contrast ratio to two decimal places and add it as an extra property to the object
    colorSchemes[i].contrastRatio = Math.round(contrastRatio * 100) / 100;

    // Display warning if the contrast ratio is lower than the recommended WCAG value
    if (colorSchemes[i].contrastRatio < wcagContrastRatio) {
      console.warn(`The contrast ratio for color scheme ${i + 1} is lower than the recommended value of ${wcagContrastRatio}.`);
    }
  }

  function hexToRgb(hex: string): number[] {
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    return [r, g, b];
  }

  function calculateRelativeLuminance(rgb: number[]): number {
    const [r, g, b] = rgb.map((c) => {
      const s = c / 255;
      return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
    });

    return 0.2126 * r + 0.7152 * g + 0.0722 * b;
  }

  function calculateContrastRatio(l1: number, l2: number): number {
    const lighter = Math.max(l1, l2);
    const darker = Math.min(l1, l2);
    return (lighter + 0.05) / (darker + 0.05);
  }
}
```

To use this function, simply call it with an array of color schemes:

```typescript
const colorSchemes = [
  { color1: '#ff0000', color2: '#00ff00' },
  { color1: '#0000ff', color2: '#ffffff' },
  { color1: '#333333', color2: '#444444' },
];

assessAccessibility(colorSchemes);
```

The output will include the contrast ratio for each color scheme, rounded to two decimal places:

```typescript
[
  { color1: '#ff0000', color2: '#00ff00', contrastRatio: 14.31 },
  { color1: '#0000ff', color2: '#ffffff', contrastRatio: 8.59 },
  { color1: '#333333', color2: '#444444', contrastRatio: 4.21 },
]
```

If the contrast ratio is lower than the recommended value of 4.5, a warning message will be displayed in the console:

```
The contrast ratio for color scheme 3 is lower than the recommended value of 4.5.
```

