// canvas setup
const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');

// snowflake settings
const snowflakes = [];
const maxSnowflakes = 1000;
const snowflakeStyles = ['circle', 'square'];
const snowflakeSpeed = 1; // in pixels per frame
const snowflakeAngle = 90; // in degrees
const snowflakeSize = 5; // in pixels
const snowflakeDensity = 10; // number of snowflakes per frame

// environment settings
const bgColor = '#000000';
const buildingColor = '#333333';
const treeColor = '#804000';

// create a snowflake object
function createSnowflake() {
  const style = snowflakeStyles[Math.floor(Math.random() * snowflakeStyles.length)];
  const speed = Math.random() * snowflakeSpeed;
  const angle = Math.random() * snowflakeAngle;
  const size = Math.random() * snowflakeSize;
  const x = Math.random() * canvas.width;
  const y = 0;
  
  return { style, speed, angle, size, x, y };
}

// draw a snowflake
function drawSnowflake(snowflake) {
  const { style, size, x, y } = snowflake;
  
  ctx.beginPath();
  
  if (style === 'circle') {
    ctx.arc(x, y, size / 2, 0, 2 * Math.PI);
  } else if (style === 'square') {
    ctx.rect(x - size / 2, y - size / 2, size, size);
  }
  
  ctx.fillStyle = '#FFFFFF';
  ctx.fill();
}

// clear the canvas
function clearCanvas() {
  ctx.fillStyle = bgColor;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
}

// generate a new frame of snowfall
function generateSnowfall() {
  clearCanvas();
  
  // create new snowflakes
  for (let i = 0; i < snowflakeDensity; i++) {
    if (snowflakes.length < maxSnowflakes) {
      snowflakes.push(createSnowflake());
    }
  }
  
  // update and draw snowflakes
  for (let i = 0; i < snowflakes.length; i++) {
    const snowflake = snowflakes[i];
    
    snowflake.y += snowflake.speed * Math.sin(snowflake.angle * Math.PI / 180);
    snowflake.x += snowflake.speed * Math.cos(snowflake.angle * Math.PI / 180);
    
    if (snowflake.y > canvas.height) {
      snowflakes.splice(i, 1);
    } else {
      drawSnowflake(snowflake);
    }
  }
  
  // draw buildings and trees
  ctx.fillStyle = buildingColor;
  ctx.fillRect(100, 200, 200, 300);
  ctx.fillStyle = treeColor;
  ctx.beginPath();
  ctx.moveTo(400, 300);
  ctx.lineTo(450, 250);
  ctx.lineTo(500, 300);
  ctx.lineTo(475, 300);
  ctx.lineTo(475, 350);
  ctx.lineTo(450, 375);
  ctx.lineTo(425, 350);
  ctx.lineTo(425, 300);
  ctx.closePath();
  ctx.fill();
  
  // call this function again on the next frame
  requestAnimationFrame(generateSnowfall);
}

// start the snowfall animation
requestAnimationFrame(generateSnowfall);
```

