```js
class BowlingGame {
  constructor() {
    this.frames = [];
    this.currentFrame = [];
    this.score = 0;
    this.currentRoll = 0;
  }

  roll(pins) {
    if (this.currentRoll === 0) {
      this.currentFrame = [pins];
      this.currentRoll++;
    } else {
      this.currentFrame.push(pins);
      this.frames.push(this.currentFrame);
      this.currentRoll = 0;
    }
  }

  calculateScore() {
    let frameIndex = 0;
    for (let i = 0; i < 10; i++) {
      if (this.isStrike(frameIndex)) {
        this.score += 10 + this.strikeBonus(frameIndex);
        frameIndex++;
      } else if (this.isSpare(frameIndex)) {
        this.score += 10 + this.spareBonus(frameIndex);
        frameIndex += 2;
      } else {
        this.score += this.sumOfBallsInFrame(frameIndex);
        frameIndex += 2;
      }
    }
    return this.score;
  }

  isSpare(frameIndex) {
    return this.frames[frameIndex][0] + this.frames[frameIndex][1] === 10;
  }

  isStrike(frameIndex) {
    return this.frames[frameIndex][0] === 10;
  }

  sumOfBallsInFrame(frameIndex) {
    return this.frames[frameIndex][0] + this.frames[frameIndex][1];
  }

  spareBonus(frameIndex) {
    return this.frames[frameIndex + 1][0];
  }

  strikeBonus(frameIndex) {
    if (this.isStrike(frameIndex + 1)) {
      return 10 + this.frames[frameIndex + 2][0];
    } else {
      return this.frames[frameIndex + 1][0] + this.frames[frameIndex + 1][1];
    }
  }
}

describe('Bowling Game', () => {
  let game;

  beforeEach(() => {
    game = new BowlingGame();
  });

  it('should be able to score a gutter game', () => {
    rollMany(game, 20, 0);
    expect(game.calculateScore()).toEqual(0);
  });

  it('should be able to score a game of all ones', () => {
    rollMany(game, 20, 1);
    expect(game.calculateScore()).toEqual(20);
  });

  it('should be able to score a spare followed by three pins', () => {
    rollSpare(game);
    game.roll(3);
    rollMany(game, 17, 0);
    expect(game.calculateScore()).toEqual(16);
  });

  it('should be able to score a strike followed by three and four pins', () => {
    rollStrike(game);
    game.roll(3);
    game.roll(4);
    rollMany(game, 16, 0);
    expect(game.calculateScore()).toEqual(24);
  });

  it('should be able to score a perfect game', () => {
    rollMany(game, 12, 10);
    expect(game.calculateScore()).toEqual(300);
  });

  function rollMany(game, rolls, pins) {
    for (let i = 0; i < rolls; i++) {
      game.roll(pins);
    }
  }

  function rollSpare(game) {
    game.roll(5);
    game.roll(5);
  }

  function rollStrike(game) {
    game.roll(10);
  }
});
```

